bashkit.tool_input_schema:
{
  "properties": {
    "commands": {
      "description": "Bash commands to execute",
      "type": "string"
    },
    "timeout_ms": {
      "description": "Optional per-call timeout in milliseconds",
      "format": "uint64",
      "minimum": 0,
      "type": [
        "integer",
        "null"
      ]
    }
  },
  "required": [
    "commands"
  ],
  "type": "object"
}
